example.code:
USE ROLE USERADMIN;
CREATE ROLE MARTS_READ;               -- access role: what can be read
CREATE ROLE ANALYST;                  -- functional role: a job
GRANT ROLE MARTS_READ TO ROLE ANALYST;
GRANT ROLE ANALYST TO ROLE SYSADMIN;  -- keep the hierarchy connected

USE ROLE SECURITYADMIN;
GRANT USAGE ON DATABASE ACME TO ROLE MARTS_READ;
GRANT USAGE ON SCHEMA ACME.MARTS TO ROLE MARTS_READ;
GRANT SELECT ON ALL TABLES IN SCHEMA ACME.MARTS TO ROLE MARTS_READ;
GRANT SELECT ON FUTURE TABLES IN SCHEMA ACME.MARTS TO ROLE MARTS_READ;
GRANT USAGE ON WAREHOUSE BI_WH TO ROLE ANALYST;

-- Enterprise edition, as a governance role allowed to create and apply policies
USE ROLE GOVERNANCE_ADMIN;
CREATE MASKING POLICY ACME.MARTS.EMAIL_MASK AS (val STRING) RETURNS STRING ->
  CASE WHEN IS_ROLE_IN_SESSION('PII_READER') THEN val
       ELSE REGEXP_REPLACE(val, '.+@', '*****@') END;
ALTER TABLE ACME.MARTS.DIM_CUSTOMER MODIFY COLUMN email
  SET MASKING POLICY ACME.MARTS.EMAIL_MASK;

-- More than 1 day of time travel needs Enterprise edition
ALTER TABLE ACME.MARTS.FCT_ORDERS SET DATA_RETENTION_TIME_IN_DAYS = 30;

-- The table just before a bad statement (query id from the query history)
SELECT COUNT(*) FROM ACME.MARTS.FCT_ORDERS
  BEFORE(STATEMENT => '01b2c3d4-0000-1a2b-0000-00012345abcd');

-- After an accidental DROP TABLE (rename first if the name was reused)
UNDROP TABLE ACME.STAGING.ORDERS;

-- A full dev copy of production in seconds
CREATE DATABASE ACME_DEV CLONE ACME;

-- Rebuildable data: no fail-safe, at most 1 day of time travel
CREATE TRANSIENT TABLE ACME.STAGING.ORDERS_TMP (order_id NUMBER, status STRING);

-- Share a secure view with a partner account (no data copied)
CREATE SHARE ACME_PARTNER_SHARE;
GRANT USAGE ON DATABASE ACME TO SHARE ACME_PARTNER_SHARE;
GRANT USAGE ON SCHEMA ACME.MARTS TO SHARE ACME_PARTNER_SHARE;
GRANT SELECT ON VIEW ACME.MARTS.V_PARTNER_SALES TO SHARE ACME_PARTNER_SHARE;
ALTER SHARE ACME_PARTNER_SHARE ADD ACCOUNTS = PARTNERORG.PARTNER_ACCT;

exercises.answer:
CREATE ROW ACCESS POLICY ACME.MARTS.COUNTRY_RAP
  AS (country STRING) RETURNS BOOLEAN ->
    IS_ROLE_IN_SESSION('SALES_ADMIN')
    OR (IS_ROLE_IN_SESSION('SALES_FR') AND country = 'FR');

ALTER TABLE ACME.MARTS.FCT_ORDERS
  ADD ROW ACCESS POLICY ACME.MARTS.COUNTRY_RAP ON (country);

